import bpy
hoop = bpy.data.objects.get('GEO_F1_Halo_Hoop')
if hoop:
    print('Halo_Hoop:', hoop.type, [m.name if m else None for m in hoop.data.materials])
for m in sorted(bpy.data.materials, key=lambda x: x.name):
    print('--- MAT:', m.name, 'users=', m.users)
    if m.node_tree:
        for n in m.node_tree.nodes:
            vals = {}
            for inp in n.inputs:
                if inp.is_linked:
                    vals[inp.name] = 'LINKED(' + inp.links[0].from_node.type + '.' + inp.links[0].from_socket.name + ')'
                else:
                    try:
                        v = inp.default_value
                        vals[inp.name] = tuple(round(float(x),4) for x in v) if hasattr(v, '__len__') else round(float(v),4)
                    except Exception:
                        pass
            img = getattr(n, 'image', None)
            extra = f' img={img.name}({img.size[0]}x{img.size[1]})' if img else ''
            print(f'  NODE {n.type} ({n.name}){extra}: {vals}')
"

